INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Israel x Iran ceasefire continues through August 9?', 'This market will resolve to "Yes" if a state of ceasefire remains in effect between Israel and Iran through the listed date, 11:59 PM Iran Standard Time (IRST). Otherwise this market will resolve to “No”. A state of ceasefire will be considered to no longer be in effect between Israel and Iran if either Israel or Iran takes a qualifying military action against the other country between market creation and the listed date, 11:59 PM IRST. A qualifying military action refers to an air strike or a s', 'politics', 'active', 1161582.08, 11733.15, 1162082.08, 12233.15);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Iran leadership change by December 31?', 'This market will resolve to "Yes" if the Supreme Leader of Iran, Mojtaba Khamenei, ceases to be the de facto leader of Iran at any point between market creation and the listed date (ET). Otherwise, this market will resolve to "No". Mojtaba Khamenei will be considered to no longer be the de facto leader of Iran if he is removed from power, is detained, or otherwise loses his position or is prevented from acting as the de facto leader of Iran within this market''s timeframe. An official announceme', 'politics', 'active', 366478.58, 1614486.73, 366978.58, 1614986.73);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Donald Trump win the Nobel Peace Prize in 2026?', 'This market will resolve according to the winner of the 2026 Nobel Peace Prize, as announced by the Norwegian Nobel Committee. If multiple listed individuals or entities jointly receive the prize, the market will resolve to a single winner. If Donald Trump, Volodymyr Zelenskyy, Benjamin Netanyahu, Vladimir Putin, or Elon Musk are among the recipients, the market will resolve to the highest-ranked among them in that exact order of precedence. If none of those five are among the winners and the pr', 'politics', 'active', 57302.45, 2105054.18, 57802.45, 2105554.18);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Reza Pahlavi enter Iran by December 31?', 'If Reza Pahlavi visits Iran between market creation and December 31, 2026 11:59 PM ET, this market will resolve to "Yes". Otherwise, this market will resolve to "No". For the purpose of this market, a "visit" is defined as Reza Pahlavi physically entering the terrestrial territory of Iran. Whether or not Reza Pahlavi enters Iranian airspace or maritime territory during the timeframe of this market will have no bearing on a positive resolution. The primary resolution source for this market will b', 'politics', 'active', 60130.92, 1033158.58, 60630.92, 1033658.58);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Putin out as President of Russia by December 31, 2026?', 'This market will resolve to “Yes” if Vladimir Putin ceases to be President of Russia for any period of time between market creation and the specified date (ET). Otherwise, this market will resolve to “No”. An announcement of Vladimir Putin''s resignation/removal before this market''s end date will immediately resolve this market to "Yes", regardless of when the announced resignation/removal goes into effect. If the specified individual is detained, effectively removed from the specified position', 'politics', 'active', 702422.32, 8663208.59, 702922.32, 8663708.59);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Columbus Crew win the 2026 MLS Cup?', 'This market will resolve according to the team that wins the 2026 MLS Cup. If at any point it becomes impossible for a listed team to win the 2026 MLS Cup per the rules of MLS (e.g. they are mathematically eliminated), the corresponding market will resolve to “No”. If the 2026 MLS season is cancelled, postponed after December 31, 2026 ET, or there is otherwise no winner declared within that timeframe, this market will resolve to “Other”. The primary resolution source will be official information', 'sports', 'active', 21011.64, 1535406.06, 21511.64, 1535906.06);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will United Russia (ER) gain the most seats in the next Russian parliamentary election?', 'Parliamentary elections are to be scheduled to be held in Russia in September 2026. This market will resolve according to the political party that gains the greatest number of seats in the next Russian State Duma election, compared to before the election. If the results are not known definitively by September 30, 2027, 11:59 PM ET, this market will resolve to "Other". In the event of a tie between multiple parties for the most seats gained, this market will resolve in favor of the party that rec', 'politics', 'active', 2238564.5, 1077827.35, 2239064.5, 1078327.35);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Strait of Hormuz traffic returns to normal by August 31?', 'This market will resolve to “Yes” if IMF Portwatch publishes a 7-day moving average of transit calls (“Arrivals of Ships”) for the Strait of Hormuz equal to or above 60 for any date between market creation and August 31, 2026. Otherwise, this market will resolve to “No”. Daily transit calls include container, dry bulk, roll-on/roll-off, general cargo, and tanker ships. Ships not reported by IMF Portwatch will not be considered. This market will resolve as soon as IMF Portwatch publishes a 7-day ', 'politics', 'active', 169544.78, 5995719.97, 170044.78, 5996219.97);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Nebius Group be acquired before 2027?', 'This market will resolve to “Yes” if credible reporting confirms that any entity enters into an agreement to acquire the listed company by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No”. Mergers where the listed company is subsumed by another entity will count toward a "Yes" resolution. An announced agreement between the listed company and an acquiring entity will qualify for a “Yes” resolution, regardless of whether the acquisition is ultimately completed. The prima', 'tech', 'active', 254466.8, 3721576.94, 254966.8, 3722076.94);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Hantavirus pandemic in 2026?', 'This market will resolve to "Yes" if the World Health Organization explicitly characterizes Hantavirus, Hantavirus Pulmonary Syndrome (HPS), Hemorrhagic Fever with Renal Syndrome (HFRS), or a Hantavirus-related outbreak as a "pandemic" in an official public communication between market creation and December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". An explicit characterization includes official WHO statements, reports, press briefings, or publications that clearly descr', 'general', 'active', 338330.64, 8565107.36, 338830.64, 8565607.36);